(() => {
  const F = window.SOSFinance;
  const S = window.SOSStorage;
  const root = document.getElementById('app');
  const modalRoot = document.getElementById('modal-root');
  const toastRoot = document.getElementById('toast-root');
  const ui = { state: null, route: 'home', month: F.monthKey(new Date()), manageTab: 'transactions', cardManageId: null };

  function historyPayload(modal = false) {
    return { sosFinanca: true, route: ui.route, month: ui.month, manageTab: ui.manageTab, cardManageId: ui.cardManageId, modal };
  }

  function ensureHistory() {
    if (!history.state?.sosFinanca) history.replaceState(historyPayload(false), '');
  }

  function pushHistory(modal = false) {
    ensureHistory();
    history.pushState(historyPayload(modal), '');
  }

  function replaceHistory(modal = false) {
    ensureHistory();
    history.replaceState(historyPayload(modal), '');
  }

  function closeModal(useBack = false) {
    const hadModalHistory = Boolean(history.state?.sosFinanca && history.state.modal);
    modalRoot.innerHTML = '';
    if (useBack && hadModalHistory && history.length > 1) history.back();
    else if (hadModalHistory) replaceHistory(false);
  }

  const e = value => String(value ?? '').replace(/[&<>'"]/g, ch => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', "'":'&#39;', '"':'&quot;' }[ch]));
  const num = v => Number(v || 0);
  const pct = (a, b) => b > 0 ? Math.min(100, Math.round(a / b * 100)) : 0;
  const sum = (list, fn = x => x) => list.reduce((a, x) => a + Number(fn(x) || 0), 0);
  const selected = (a, b) => String(a ?? '') === String(b ?? '') ? 'selected' : '';
  const checked = v => v ? 'checked' : '';

  const icons = {
    logo:'M4 12h4l2-5 4 10 2-5h4 M12 2v4 M12 18v4', home:'M3 11.5 12 4l9 7.5V21h-6v-6H9v6H3z',
    calendar:'M4 5h16v16H4z M8 3v4 M16 3v4 M4 9h16', wallet:'M3 6h17v14H3z M3 6l3-3h11l3 3 M15 12h5',
    card:'M3 6h18v13H3z M3 10h18 M7 15h4', receipt:'M5 3h14v18l-3-2-2 2-2-2-2 2-2-2-3 2z M8 8h8 M8 12h8',
    target:'M12 3a9 9 0 1 0 9 9 M12 7a5 5 0 1 0 5 5 M12 11a1 1 0 1 0 1 1 M14 10l7-7 M17 3h4v4',
    chart:'M4 20V10 M10 20V4 M16 20v-7 M22 20H2', plus:'M12 5v14 M5 12h14', settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M4 12H2 M22 12h-2 M12 4V2 M12 22v-2 M5.6 5.6 4.2 4.2 M18.4 18.4l-4.2-4.2 M18.4 5.6l-4.2 4.2 M5.6 18.4l4.2-4.2',
    edit:'M4 20h4L19 9l-4-4L4 16z M13 7l4 4', trash:'M4 7h16 M9 7V4h6v3 M7 7l1 14h8l1-14',
    arrowLeft:'M15 18l-6-6 6-6', arrowRight:'M9 18l6-6-6-6', chevronRight:'M9 18l6-6-6-6',
    bank:'M3 9h18 M5 9v9 M9 9v9 M15 9v9 M19 9v9 M3 21h18 M12 3l9 4H3z', transfer:'M5 8h14l-3-3 M19 16H5l3 3',
    coins:'M12 6c4.4 0 8-1.3 8-3s-3.6-3-8-3-8 1.3-8 3 3.6 3 8 3z M4 3v5c0 1.7 3.6 3 8 3s8-1.3 8-3V3 M4 8v5c0 1.7 3.6 3 8 3s8-1.3 8-3V8 M4 13v5c0 1.7 3.6 3 8 3s8-1.3 8-3v-5',
    alert:'M12 3 2 21h20z M12 9v5 M12 18h.01', check:'M5 12l4 4L19 6', close:'M6 6l12 12 M18 6L6 18',
    menu:'M4 6h16 M4 12h16 M4 18h16', moon:'M20 15a8 8 0 0 1-11-11 8.5 8.5 0 1 0 11 11z', sun:'M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10 M12 2v2 M12 20v2 M4.9 4.9l1.4 1.4 M17.7 17.7l1.4 1.4 M2 12h2 M20 12h2 M4.9 19.1l1.4-1.4 M17.7 6.3l1.4-1.4',
    download:'M12 3v12 M7 10l5 5 5-5 M4 21h16', refresh:'M20 7h-5V2 M4 17h5v5 M19 12a7 7 0 0 0-12-5L4 10 M5 12a7 7 0 0 0 12 5l3-3',
    lock:'M6 10h12v11H6z M8 10V7a4 4 0 0 1 8 0v3', info:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20 M12 10v7 M12 7h.01',
    search:'M11 19a8 8 0 1 1 0-16 8 8 0 0 1 0 16 M17 17l5 5', more:'M5 12h.01 M12 12h.01 M19 12h.01'
  };
  function icon(name, cls='') {
    const d = icons[name] || icons.receipt;
    return `<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${d}"/></svg>`;
  }

  function toast(message, type='good') {
    const el = document.createElement('div'); el.className = `toast ${type}`; el.textContent = message; toastRoot.appendChild(el);
    setTimeout(() => el.remove(), 3000);
  }

  function applyTheme() {
    const pref = ui.state?.profile?.theme || 'system';
    let theme = pref;
    if (theme === 'system') theme = matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
    document.documentElement.dataset.theme = theme;
  }

  async function reload(render = true) {
    ui.state = await S.getState();
    applyTheme();
    if (render) renderApp();
  }

  function navItem(route, label, ic, badge='') {
    return `<button class="nav-item ${ui.route === route ? 'active' : ''}" data-route="${route}">${icon(ic)}<span>${label}</span>${badge ? `<span class="nav-badge">${badge}</span>` : ''}</button>`;
  }

  function shell(content, title, subtitle='') {
    const overdueCount = F.dueBuckets(ui.state, F.monthKey(new Date())).overdue.length;
    return `<div class="app-shell">
      <aside class="sidebar">
        <div class="brand"><div class="brand-mark">${icon('logo')}</div><div><strong>SOS Finança</strong><small>Seu dinheiro, sob controle</small></div></div>
        <div class="nav-section">CONSULTAR</div>
        ${navItem('home','Início','home',overdueCount || '')}
        ${navItem('month','Mês','calendar')}
        ${navItem('accounts','Contas','wallet')}
        ${navItem('cards','Cartões','card')}
        ${navItem('debts','Dívidas','receipt')}
        ${navItem('budget','Orçamento','target')}
        ${navItem('reports','Relatórios','chart')}
        <div class="nav-section">GERENCIAR</div>
        ${navItem('manage','Dados financeiros','edit')}
        <div class="sidebar-spacer"></div>
        ${navItem('settings','Configurações','settings')}
        <div class="sidebar-user"><div class="avatar">${e((ui.state.profile?.name || 'U').charAt(0).toUpperCase())}</div><div><strong>${e(ui.state.profile?.name || 'Usuário')}</strong><span>${ui.state.profile?.usageMode === 'household' ? 'Gestão da casa' : 'Finanças pessoais'}</span></div></div>
      </aside>
      <main class="main">
        <header class="topbar">
          <div class="page-heading"><h1>${e(title)}</h1><p>${e(subtitle)}</p></div>
          <div class="top-actions">
            <div class="month-picker"><button data-month-shift="-1" aria-label="Mês anterior">${icon('arrowLeft')}</button><span>${e(F.monthLabel(ui.month))}</span><button data-month-shift="1" aria-label="Próximo mês">${icon('arrowRight')}</button></div>
            <button class="icon-btn" data-theme-toggle aria-label="Alternar tema">${icon(document.documentElement.dataset.theme === 'dark' ? 'sun' : 'moon')}</button>
            ${ui.route !== 'manage' ? `<button class="secondary-btn btn-sm" data-route="manage">${icon('edit')} Gerenciar</button>` : ''}
          </div>
        </header>
        <div class="content">${content}</div>
      </main>
      <button class="fab" data-action="quick" title="Gasto rápido">${icon('plus')}</button>
      <nav class="mobile-nav">
        ${mobileItem('home','Início','home')}${mobileItem('month','Mês','calendar')}${mobileItem('debts','Dívidas','receipt')}${mobileItem('cards','Cartões','card')}${mobileItem('more','Mais','menu')}
      </nav>
    </div>`;
  }

  function mobileItem(route,label,ic){
    const active = route === 'more' ? ['accounts','budget','reports','manage','settings'].includes(ui.route) : ui.route === route;
    return `<button class="mobile-item ${active?'active':''}" data-route="${route}">${icon(ic)}<span>${label}</span></button>`;
  }

  function setupPage() {
    root.innerHTML = `<div class="setup"><div class="setup-card">
      <div class="setup-hero"><div class="setup-logo">${icon('logo')}</div><h1>Bem-vindo ao SOS Finança</h1><p>Um controle financeiro local, direto e sem distrações. Seus dados ficam neste aparelho e o aplicativo foi pensado para mostrar a situação primeiro e deixar a edição em uma área separada.</p></div>
      <form class="setup-body" data-form="setup"><h2>Vamos preparar sua instalação</h2><p>Isso leva menos de um minuto e pode ser alterado depois.</p>
        <div class="form-field full"><label>Como podemos chamar você?</label><input name="name" maxlength="60" placeholder="Ex.: Rodolfo, Pai, Maria (opcional)"></div>
        <div style="height:16px"></div><div class="form-field full"><label>Como você vai usar esta instalação?</label>
          <div class="radio-cards">
            <label class="radio-card"><input type="radio" name="usageMode" value="household" checked><strong>Gerenciar a casa</strong><span>Contas, financiamentos, cartões, feira e despesas da casa inteira.</span></label>
            <label class="radio-card"><input type="radio" name="usageMode" value="personal"><strong>Finanças pessoais</strong><span>Meu salário, minhas contas, cartões, metas e gastos individuais.</span></label>
          </div>
        </div>
        <div class="setup-foot"><div class="privacy-note">${icon('lock')}<span>Sem conta online e sem nuvem. Cada instalação possui seus próprios dados locais.</span></div><button class="primary-btn" type="submit">Começar meu controle ${icon('arrowRight')}</button></div>
      </form>
    </div></div>`;
  }

  function metric(label, value, foot, kind='', ic='wallet') {
    return `<div class="metric ${kind}"><div class="metric-head"><span>${e(label)}</span><div class="metric-icon">${icon(ic)}</div></div><div class="metric-value">${e(value)}</div><div class="metric-foot">${e(foot)}</div></div>`;
  }

  function empty(title, text, ic='info') { return `<div class="empty">${icon(ic)}<strong>${e(title)}</strong>${e(text)}</div>`; }

  function homePage() {
    const st=ui.state, key=ui.month, currentKey=F.monthKey(new Date()), sm=F.monthSummary(st,key), balance=F.currentBalance(st);
    const openDebts=(st.debts||[]).filter(d=>F.debtIsOpen(st,d));
    const totalDebt=sum(openDebts.filter(F.debtHasKnownBalance),d=>F.debtBalance(st,d));
    const unknownDebtCount=openDebts.filter(d=>!F.debtHasKnownBalance(d)).length;
    const due=F.dueBuckets(st,currentKey);
    const remainingIncome=Math.max(0,sm.incomePlanned-sm.incomeRealized), remainingExpense=Math.max(0,sm.expensesPlanned-sm.expensesRealized);
    const projectedClosing=sm.projected;
    let alert='';
    if(due.overdue.length) alert=`<div class="alert-strip danger">${icon('alert')}<div><strong>${due.overdue.length} compromisso${due.overdue.length>1?'s':''} em atraso</strong><span>${F.money(sum(due.overdue,x=>Math.max(0,x.amountCents-x.paidCents)))} ainda precisa ser regularizado.</span></div></div>`;
    else if(due.next7.length) alert=`<div class="alert-strip warn">${icon('calendar')}<div><strong>${due.next7.length} pagamento${due.next7.length>1?'s':''} nos próximos 7 dias</strong><span>Prepare ${F.money(sum(due.next7,x=>Math.max(0,x.amountCents-x.paidCents)))} para os próximos vencimentos.</span></div></div>`;
    else if(!(st.accounts||[]).length) alert=`<div class="alert-strip warn">${icon('bank')}<div><strong>Cadastre sua primeira conta</strong><span>Sem uma conta ou carteira, o app consegue analisar gastos, mas não consegue mostrar seu saldo disponível real.</span></div></div>`;
    else alert=`<div class="alert-strip">${icon('check')}<div><strong>Nenhum vencimento urgente</strong><span>Continue registrando os gastos para manter esta visão confiável.</span></div></div>`;

    const agenda=F.monthAgenda(st,key).filter(x=>x.kind==='expense').slice(0,6);
    const cat=F.expenseByCategory(st,key).slice(0,5), catMax=Math.max(1,...cat.map(x=>x.amountCents));
    const debts=openDebts.slice().sort((a,b)=>F.debtBalance(st,b)-F.debtBalance(st,a)).slice(0,4);
    return shell(`${alert}<div class="hero-grid">
      ${metric('Saldo disponível',F.money(balance),'Dinheiro nas contas agora',balance>=0?'good':'danger','wallet')}
      ${metric('Dívida total conhecida',F.money(totalDebt),`${openDebts.length} dívida(s) em aberto${unknownDebtCount?` · ${unknownDebtCount} sem saldo informado`:''}`,totalDebt>0?'warn':'good','receipt')}
      ${metric('A pagar no mês',F.money(sm.expensesPlanned),`Realizado: ${F.money(sm.expensesRealized)}`,sm.expensesPlanned>sm.incomePlanned?'warn':'','calendar')}
      ${metric('Saldo previsto do mês',F.money(projectedClosing),'Receitas do mês - contas, faturas e parcelas do mês',projectedClosing>=0?'good':'danger','chart')}
    </div>
    <div class="grid-2"><section class="panel"><div class="panel-head"><div><h3>Próximos compromissos</h3><small>${e(F.monthLabel(key))}</small></div><button class="link-btn" data-route="month">Ver mês completo</button></div>
      ${agenda.length?`<div class="list">${agenda.map(agendaRow).join('')}</div>`:empty('Mês tranquilo','Nenhum compromisso financeiro cadastrado para este mês.','calendar')}
    </section><section class="panel"><div class="panel-head"><div><h3>Onde o dinheiro está indo</h3><small>Despesas por categoria</small></div></div>
      ${cat.length?cat.map(x=>`<div class="budget-row"><div class="budget-meta"><strong>${e(F.categoryName(st,x.categoryId))}</strong><span>${F.money(x.amountCents)}</span></div><div class="progress"><span style="width:${Math.max(4,Math.round(x.amountCents/catMax*100))}%"></span></div></div>`).join(''):empty('Ainda sem gastos','Os gastos registrados aparecem aqui por categoria.','chart')}
    </section></div>
    <div class="grid-equal"><section class="panel"><div class="panel-head"><div><h3>Mapa das dívidas</h3><small>Saldo devedor atual</small></div><button class="link-btn" data-route="debts">Ver central</button></div>
      ${debts.length?`<div class="list">${debts.map(d=>`<div class="list-row"><div class="row-icon">${icon('receipt')}</div><div class="row-main"><strong>${e(d.name)}</strong><span>${e(d.creditor||debtTypeLabel(d.debtType))}</span></div><div class="row-amount">${F.debtHasKnownBalance(d)?F.money(F.debtBalance(st,d)):'Saldo não informado'}</div></div>`).join('')}</div>`:empty('Sem dívidas cadastradas','Se houver empréstimos ou financiamentos, registre em Gerenciar.','check')}
    </section><section class="panel"><div class="panel-head"><div><h3>Orçamento do mês</h3><small>Limites por categoria</small></div><button class="link-btn" data-route="budget">Ver orçamento</button></div>${budgetMini(st,key)}</section></div>`, 'Visão geral', 'Situação financeira em uma única tela');
  }

  function agendaRow(item) {
    const remaining=Math.max(0,item.amountCents-item.paidCents), status={paid:'Pago',pending:'Pendente',overdue:'Atrasado'}[item.status]||item.status;
    return `<div class="list-row"><div class="row-icon">${icon(item.type==='card'?'card':item.type==='debt'?'receipt':'calendar')}</div><div class="row-main"><strong>${e(item.label)}</strong><span>${item.noDueDate?'Sem vencimento informado':`Vence ${e(F.dateLabel(item.dueDate))}`} · <span class="row-status status-${item.status}">${status}</span></span></div><div class="row-amount ${item.kind}">${item.kind==='income'?'+':'-'} ${F.money(remaining || item.amountCents)}</div></div>`;
  }

  function monthPage(){
    const st=ui.state,key=ui.month,sm=F.monthSummary(st,key),agenda=F.monthAgenda(st,key),today=F.todayKey();
    const [y,m]=key.split('-').map(Number), days=new Date(y,m,0).getDate();
    const anchor=key===F.monthKey(new Date())?Math.min(new Date().getDate(),days):1;
    const start=Math.max(1,Math.min(anchor-3,Math.max(1,days-6)));
    const calendar=Array.from({length:Math.min(7,days)},(_,i)=>{const d=start+i,wd=new Date(y,m-1,d,12).getDay();return `<div class="cal-day ${`${key}-${F.pad(d)}`===today?'today':''}">${['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'][wd]}<strong>${d}</strong></div>`}).join('');
    const groups={}; agenda.forEach(x=>(groups[x.dueDate]??=[]).push(x));
    return shell(`<div class="hero-grid">
      ${metric('Receitas previstas',F.money(sm.incomePlanned),`Recebido: ${F.money(sm.incomeRealized)}`,'good','wallet')}
      ${metric('Despesas previstas',F.money(sm.expensesPlanned),`Pago/realizado: ${F.money(sm.expensesRealized)}`,sm.expensesPlanned>sm.incomePlanned?'warn':'','receipt')}
      ${metric('Resultado previsto',F.money(sm.projected),'Planejamento completo do mês',sm.projected>=0?'good':'danger','chart')}
      ${metric('Resultado realizado',F.money(sm.realized),'Somente o que já aconteceu',sm.realized>=0?'good':'danger','check')}
    </div><div class="grid-2"><section class="panel"><div class="panel-head"><div><h3>Agenda financeira</h3><small>Contas, faturas e parcelas</small></div></div><div class="calendar-strip">${calendar}</div>
      ${agenda.length?Object.entries(groups).map(([date,items])=>`<div class="agenda-day">${F.dateLabel(date)}</div>${items.map(agendaRow).join('')}`).join(''):empty('Nada previsto','Cadastre compromissos, cartões ou dívidas para montar sua agenda.','calendar')}
    </section><section class="panel"><div class="panel-head"><div><h3>Composição do mês</h3><small>Sem contar a fatura duas vezes</small></div></div>
      ${compositionRow('Despesas avulsas',sm.directExpense,sm.expensesPlanned)}${compositionRow('Contas recorrentes',sm.recurringExpense,sm.expensesPlanned)}${compositionRow('Faturas de cartão',sm.cardPlanned,sm.expensesPlanned)}${compositionRow('Parcelas de dívidas',sm.debtPlanned,sm.expensesPlanned)}
      <div class="alert-strip" style="margin-top:14px;margin-bottom:0">${icon('info')}<div><strong>Compra no cartão não baixa a conta bancária</strong><span>Ela entra na fatura. O dinheiro sai da conta somente quando a fatura é paga.</span></div></div>
    </section></div>`, 'Mês', 'O que entrou, saiu e ainda vai vencer');
  }
  function compositionRow(label,value,total){return `<div class="budget-row"><div class="budget-meta"><strong>${e(label)}</strong><span>${F.money(value)}</span></div><div class="progress"><span style="width:${pct(value,total)}%"></span></div></div>`}

  function accountsPage(){
    const st=ui.state, accounts=st.accounts||[];
    return shell(`<div class="section-title"><div><h2>Minhas contas</h2><p>Saldo consolidado e onde o dinheiro está.</p></div></div>
      <div class="hero-grid">${metric('Saldo consolidado',F.money(F.currentBalance(st)),'Soma de todas as contas',F.currentBalance(st)>=0?'good':'danger','wallet')}${metric('Contas cadastradas',String(accounts.length),'Bancos, carteira e dinheiro','','bank')}${metric('Entradas no mês',F.money(F.monthSummary(st,ui.month).incomeRealized),'Valores já recebidos','good','plus')}${metric('Saídas no mês',F.money(F.monthSummary(st,ui.month).expensesRealized),'Valores já pagos','','receipt')}</div>
      <div class="grid-equal"><section class="panel"><div class="panel-head"><h3>Saldos</h3><small>Atualizados pelos registros</small></div>${accounts.length?`<div class="list">${accounts.map(a=>`<div class="account-card"><div class="account-icon">${icon('bank')}</div><div class="account-info"><strong>${e(a.name)}</strong><span>${e([a.institution,a.accountType].filter(Boolean).join(' · '))}</span></div><div class="account-balance">${F.money(F.accountBalance(st,a.id))}</div></div>`).join('<div style="height:8px"></div>')}</div>`:empty('Nenhuma conta cadastrada','Vá em Gerenciar → Cadastros para criar sua primeira conta.','bank')}</section>
      <section class="panel"><div class="panel-head"><h3>Transferências recentes</h3><small>Não contam como receita ou despesa</small></div>${(st.transfers||[]).length?`<div class="list">${(st.transfers||[]).slice(0,8).map(t=>`<div class="list-row"><div class="row-icon">${icon('transfer')}</div><div class="row-main"><strong>${e(F.accountName(st,t.fromAccountId))} → ${e(F.accountName(st,t.toAccountId))}</strong><span>${F.dateLabel(t.date)}${t.notes?' · '+e(t.notes):''}</span></div><div class="row-amount">${F.money(t.amountCents)}</div></div>`).join('')}</div>`:empty('Sem transferências','Transferências entre suas contas aparecem aqui.','transfer')}</section></div>`, 'Contas', 'Dinheiro disponível sem misturar com cartão');
  }

  function cardsPage(){
    const st=ui.state,key=ui.month,cards=st.cards||[];
    const totalLimit=sum(cards,c=>c.limitCents), committed=sum(cards,c=>F.cardCommitted(st,c.id)), currentInvoices=sum(cards,c=>F.invoiceFor(st,c.id,key).amountCents);
    if(cards.length && (!ui.cardManageId || !cards.some(c=>c.id===ui.cardManageId))) ui.cardManageId=cards[0].id;
    const selectedCard=cards.find(c=>c.id===ui.cardManageId)||null;
    return shell(`<div class="hero-grid">${metric('Limite total',F.money(totalLimit),'Todos os cartões','','card')}${metric('Limite comprometido',F.money(committed),'Compras ainda não quitadas',committed>totalLimit&&totalLimit>0?'danger':'warn','receipt')}${metric('Faturas do mês',F.money(currentInvoices),F.monthLabel(key),'','calendar')}${metric('Disponível estimado',totalLimit?F.money(Math.max(0,totalLimit-committed)):'Não informado',totalLimit?'Limite menos compras pendentes':'Limites são opcionais',totalLimit-committed>0?'good':'','wallet')}</div>
      <div class="section-title" style="margin-top:20px"><div><h2>Meus cartões</h2><p>Escolha um cartão para ver e cadastrar as compras dele.</p></div><button class="primary-btn btn-sm" data-action="card">${icon('plus')} Novo cartão</button></div>
      <div class="grid-3">${cards.length?cards.map(c=>cardView(st,c,key)).join(''):empty('Nenhum cartão cadastrado','Crie o cartão e depois adicione as compras diretamente nele.','card')}</div>
      ${selectedCard?cardDetail(st,selectedCard,key):''}`, 'Cartões', 'Cada cartão com suas próprias compras, faturas e pagamentos');
  }
  function cardView(st,c,key){
    const inv=F.invoiceFor(st,c.id,key),used=F.cardCommitted(st,c.id),active=ui.cardManageId===c.id;
    const closeText=num(c.closeDay)>0?`Fecha dia ${num(c.closeDay)}`:'Fechamento não informado';
    const dueText=num(c.dueDay)>0?`Vence dia ${num(c.dueDay)}`:'Vencimento não informado';
    return `<div class="card-selector ${active?'active':''}"><button type="button" class="card-open" data-card-open="${e(c.id)}"><div class="card-visual"><div class="card-bank">${e(c.bank||'Cartão de crédito')}</div><h3>${e(c.name||'Meu cartão')}</h3><div class="last4">${c.last4?`•••• ${e(c.last4)}`:'Cartão cadastrado'}</div><div class="card-spacer"></div><div class="card-info"><div><span>Fatura ${e(F.monthLabel(key).split(' ')[0])}</span><strong>${F.money(inv.amountCents)}</strong></div><div><span>Compras pendentes</span><strong>${F.money(used)}</strong></div></div></div></button><div class="card-actions"><span class="tag">${closeText}</span><span class="tag">${dueText}</span></div><div class="card-visual-btns"><button class="soft-btn btn-sm" data-card-open="${e(c.id)}">Ver compras</button><button class="primary-btn btn-sm" data-action="card-purchase-for" data-id="${e(c.id)}">${icon('plus')} Compra</button></div></div>`;
  }
  function cardDetail(st,card,key){
    const inv=F.invoiceFor(st,card.id,key),purchases=(st.cardPurchases||[]).filter(p=>p.cardId===card.id).slice().sort((a,b)=>(b.purchaseDate||'').localeCompare(a.purchaseDate||''));
    const payments=(st.cardPayments||[]).filter(p=>p.cardId===card.id&&p.invoiceMonth===key).slice().sort((a,b)=>(b.date||'').localeCompare(a.date||''));
    return `<section class="panel card-detail" style="margin-top:14px"><div class="panel-head"><div><h3>${e(card.name||'Meu cartão')} · Compras</h3><small>${purchases.length} compra(s) cadastrada(s) neste cartão</small></div><div class="section-actions"><button class="primary-btn btn-sm" data-action="card-purchase-for" data-id="${e(card.id)}">${icon('plus')} Adicionar compra</button><button class="secondary-btn btn-sm" data-action="card-payment-for" data-id="${e(card.id)}">${icon('check')} Pagar fatura</button><button class="secondary-btn btn-sm" data-edit="card" data-id="${e(card.id)}">${icon('edit')} Editar cartão</button></div></div>
      <div class="grid-equal card-detail-grid"><div><div class="mini-title"><strong>Fatura de ${e(F.monthLabel(key))}</strong><span>${F.money(inv.remainingCents)} restante</span></div>${inv.items.length?`<div class="list">${inv.items.map(x=>`<div class="list-row"><div class="row-icon">${icon('card')}</div><div class="row-main"><strong>${e(x.description||'Compra no cartão')}</strong><span>${x.index}/${x.totalInstallments} · ${e(F.categoryName(st,x.categoryId))}</span></div><div class="row-amount">${F.money(x.amountCents)}</div></div>`).join('')}</div>`:empty('Fatura sem compras','Não há parcelas calculadas para este mês.','card')}${payments.length?`<div class="form-hint" style="margin-top:10px">Pagamentos registrados neste mês: ${F.money(sum(payments,p=>p.amountCents))}</div>`:''}</div>
      <div><div class="mini-title"><strong>Todas as compras</strong><span>Mais recentes primeiro</span></div>${purchases.length?`<div class="list">${purchases.map(p=>`<div class="list-row"><div class="row-icon">${icon('receipt')}</div><div class="row-main"><strong>${e(p.description||'Compra no cartão')}</strong><span>${p.purchaseDate?F.dateLabel(p.purchaseDate):'Data não informada'} · ${num(p.installments)||1}x · ${e(F.categoryName(st,p.categoryId))}</span></div><div class="actions"><span class="row-amount">${F.money(p.totalCents)}</span><button class="action-btn" data-edit="card_purchase" data-id="${e(p.id)}" title="Editar">${icon('edit')}</button><button class="action-btn danger" data-archive="card_purchase" data-id="${e(p.id)}" title="Arquivar">${icon('trash')}</button></div></div>`).join('')}</div>`:empty('Nenhuma compra neste cartão','Use “Adicionar compra” para começar.','plus')}</div></div></section>`;
  }
  function cardInvoiceItems(st,key){const items=(st.cards||[]).flatMap(c=>F.invoiceFor(st,c.id,key).items.map(x=>({...x,cardName:c.name})));return items.length?`<div class="list">${items.slice(0,12).map(x=>`<div class="list-row"><div class="row-icon">${icon('card')}</div><div class="row-main"><strong>${e(x.description)}</strong><span>${e(x.cardName)} · ${x.index}/${x.totalInstallments} · ${e(F.categoryName(st,x.categoryId))}</span></div><div class="row-amount">${F.money(x.amountCents)}</div></div>`).join('')}</div>`:empty('Fatura sem compras','Não há parcelas previstas neste mês.','card')}
  function futureInvoices(st,key){const months=[0,1,2].map(i=>F.addMonths(key,i));return `<div class="list">${months.map(m=>{const total=sum(st.cards||[],c=>F.invoiceFor(st,c.id,m).amountCents);return `<div class="list-row"><div class="row-icon">${icon('calendar')}</div><div class="row-main"><strong>${e(F.monthLabel(m))}</strong><span>${(st.cards||[]).filter(c=>F.invoiceFor(st,c.id,m).amountCents>0).length} cartão(ões)</span></div><div class="row-amount">${F.money(total)}</div></div>`}).join('')}</div>`}

  function debtTypeLabel(type){return ({loan:'Empréstimo',car:'Financiamento de carro',motorcycle:'Financiamento de moto',card:'Dívida de cartão',personal:'Dívida pessoal',other:'Outra dívida'})[type]||'Dívida'}
  function debtsPage(){
    const st=ui.state,debts=(st.debts||[]).filter(d=>F.debtIsOpen(st,d)),known=debts.filter(F.debtHasKnownBalance),unknown=debts.filter(d=>!F.debtHasKnownBalance(d)),total=sum(known,d=>F.debtBalance(st,d)),monthly=sum(debts,d=>d.installmentCents),paidMonth=sum((st.debtPayments||[]).filter(p=>F.monthKey(p.date)===ui.month),p=>p.amountCents),interestMonth=sum((st.debtPayments||[]).filter(p=>F.monthKey(p.date)===ui.month),p=>p.interestCents);
    return shell(`<div class="hero-grid">${metric('Dívida conhecida',F.money(total),`${known.length} com saldo · ${unknown.length} sem saldo`,total?'danger':'good','receipt')}${metric('Compromisso mensal',F.money(monthly),'Soma das parcelas informadas',monthly?'warn':'','calendar')}${metric('Pago neste mês',F.money(paidMonth),'Pagamentos registrados','good','check')}${metric('Juros registrados',F.money(interestMonth),'Somente quando informado',interestMonth?'warn':'good','chart')}</div>
      <div class="section-title" style="margin-top:20px"><div><h2>Central de dívidas</h2><p>Você pode cadastrar mesmo sem lembrar data de início, juros ou saldo exato.</p></div></div>
      <div class="grid-3">${debts.length?debts.map(d=>debtCard(st,d)).join(''):empty('Nenhuma dívida em aberto','Cadastre só o que você sabe hoje; os demais dados podem ser completados depois.','check')}</div>
      ${known.length?`<div class="grid-equal"><section class="panel"><div class="panel-head"><h3>Prioridade por juros</h3><small>Somente dívidas com dados suficientes</small></div>${debtPriority(st,'interest')}</section><section class="panel"><div class="panel-head"><h3>Menores saldos primeiro</h3><small>Somente saldos conhecidos</small></div>${debtPriority(st,'balance')}</section></div>`:''}`, 'Dívidas', 'Organize primeiro; complete os detalhes quando souber');
  }
  function debtCard(st,d){
    const known=F.debtHasKnownBalance(d),bal=F.debtBalance(st,d),base=num(d.totalContractCents||d.originalCents||bal),progress=known&&base?Math.max(0,Math.min(100,Math.round((base-bal)/base*100))):null,paid=F.debtPaidCount(st,d),total=num(d.installmentsTotal);
    return `<div class="debt-card"><div class="debt-top"><div><span class="tag ${num(d.priority)<=1?'danger':num(d.priority)===2?'warn':''}">${e(debtTypeLabel(d.debtType))}</span><h3 style="margin-top:8px">${e(d.name||debtTypeLabel(d.debtType))}</h3><p>${e(d.creditor||'Credor não informado')}</p></div><span class="tag">Em aberto</span></div><div class="debt-balance">${known?F.money(bal):'Saldo não informado'}</div>${progress!==null?`<div class="progress ${progress<25?'danger':progress<60?'warn':''}"><span style="width:${progress}%"></span></div>`:'<div class="form-hint">Você pode informar o saldo devedor depois, sem perder os pagamentos registrados.</div>'}<div class="debt-grid"><div class="mini-stat"><span>Parcela</span><strong>${num(d.installmentCents)?F.money(d.installmentCents):'—'}</strong></div><div class="mini-stat"><span>Parcelas</span><strong>${total?`${paid}/${total}`:'—'}</strong></div><div class="mini-stat"><span>Vencimento</span><strong>${num(d.dueDay)?`Dia ${num(d.dueDay)}`:'—'}</strong></div></div>${progress!==null?`<div class="tag good">${progress}% reduzido</div>`:''}</div>`;
  }
  function debtPriority(st,mode){let arr=(st.debts||[]).filter(d=>F.debtIsOpen(st,d)&&F.debtHasKnownBalance(d));arr.sort(mode==='interest'?(a,b)=>num(b.interestRate)-num(a.interestRate):(a,b)=>F.debtBalance(st,a)-F.debtBalance(st,b));return arr.length?`<div class="list">${arr.slice(0,6).map((d,i)=>`<div class="list-row"><div class="row-icon"><strong>${i+1}</strong></div><div class="row-main"><strong>${e(d.name)}</strong><span>${mode==='interest'?(num(d.interestRate)?`${num(d.interestRate).toLocaleString('pt-BR')}% informado`:'Juros não informados'):`Saldo ${F.money(F.debtBalance(st,d))}`}</span></div><div class="row-amount">${mode==='interest'?F.money(F.debtBalance(st,d)):(num(d.installmentCents)?F.money(d.installmentCents):'—')}</div></div>`).join('')}</div><div class="alert-strip" style="margin:12px 0 0">${icon('info')}<div><strong>Comparação, não recomendação automática</strong><span>Use apenas como apoio para decidir o que negociar ou priorizar.</span></div></div>`:empty('Dados insuficientes','Informe saldo/juros depois se quiser comparar prioridades.','info')}

  function budgetMini(st,key){const items=(st.budgets||[]).filter(b=>b.monthKey===key),spends=new Map(F.expenseByCategory(st,key).map(x=>[x.categoryId,x.amountCents]));if(!items.length)return empty('Sem limites definidos','Crie um orçamento por categoria em Gerenciar.','target');return items.slice(0,5).map(b=>{const used=spends.get(b.categoryId)||0,p=pct(used,b.limitCents),kind=p>100?'danger':p>=80?'warn':'';return `<div class="budget-row"><div class="budget-meta"><strong>${e(F.categoryName(st,b.categoryId))}</strong><span>${F.money(used)} de ${F.money(b.limitCents)}</span></div><div class="progress ${kind}"><span style="width:${Math.min(100,p)}%"></span></div></div>`}).join('')}
  function budgetPage(){const st=ui.state,key=ui.month,items=(st.budgets||[]).filter(b=>b.monthKey===key),spends=new Map(F.expenseByCategory(st,key).map(x=>[x.categoryId,x.amountCents])),totalLimit=sum(items,b=>b.limitCents),totalUsed=sum(items,b=>spends.get(b.categoryId)||0),goals=st.goals||[];return shell(`<div class="hero-grid">${metric('Orçamento definido',F.money(totalLimit),'Limites deste mês','','target')}${metric('Já consumido',F.money(totalUsed),totalLimit?`${Math.round(totalUsed/totalLimit*100)}% do orçamento`:'Sem orçamento',totalUsed>totalLimit?'danger':totalUsed>totalLimit*.8?'warn':'','receipt')}${metric('Ainda disponível',F.money(Math.max(0,totalLimit-totalUsed)),'Dentro dos limites cadastrados',totalUsed<=totalLimit?'good':'danger','wallet')}${metric('Metas ativas',String(goals.filter(g=>g.status!=='done').length),'Objetivos financeiros','','target')}</div><div class="grid-equal"><section class="panel"><div class="panel-head"><h3>Limites por categoria</h3><small>${e(F.monthLabel(key))}</small></div>${items.length?items.map(b=>{const used=spends.get(b.categoryId)||0,p=Math.round(used/Math.max(1,b.limitCents)*100),kind=p>100?'danger':p>=80?'warn':'';return `<div class="budget-row"><div class="budget-meta"><strong>${e(F.categoryName(st,b.categoryId))}</strong><span>${F.money(used)} / ${F.money(b.limitCents)} · ${p}%</span></div><div class="progress ${kind}"><span style="width:${Math.min(100,p)}%"></span></div>${p>100?`<div class="form-hint" style="color:var(--danger)">Excedeu ${F.money(used-b.limitCents)}</div>`:''}</div>`}).join(''):empty('Orçamento ainda não montado','Defina quanto pode gastar em Feira, Combustível, Lazer e outras categorias.','target')}</section><section class="panel"><div class="panel-head"><h3>Metas financeiras</h3><small>Reserva, compra ou objetivo</small></div>${goals.length?goals.map(g=>{const p=pct(g.currentCents,g.targetCents);return `<div class="budget-row"><div class="budget-meta"><strong>${e(g.name)}</strong><span>${F.money(g.currentCents)} / ${F.money(g.targetCents)}</span></div><div class="progress"><span style="width:${p}%"></span></div>${g.dueDate?`<div class="form-hint">Meta para ${F.dateLabel(g.dueDate)}</div>`:''}</div>`}).join(''):empty('Sem metas','Você pode usar metas para reserva de emergência ou compras planejadas.','target')}</section></div>`, 'Orçamento', 'Limites simples para não descobrir o excesso no fim do mês');}

  function reportsPage(){const st=ui.state,key=ui.month,months=F.lastMonths(key,6),summaries=months.map(m=>({m,...F.monthSummary(st,m)})),max=Math.max(1,...summaries.flatMap(x=>[x.incomeRealized,x.expensesRealized])),cats=F.expenseByCategory(st,key),catMax=Math.max(1,...cats.map(x=>x.amountCents)),debtTotal=sum(st.debts||[],d=>F.debtBalance(st,d));return shell(`<div class="hero-grid">${metric('Receitas realizadas',F.money(F.monthSummary(st,key).incomeRealized),F.monthLabel(key),'good','wallet')}${metric('Despesas realizadas',F.money(F.monthSummary(st,key).expensesRealized),F.monthLabel(key),'','receipt')}${metric('Saldo do mês',F.money(F.monthSummary(st,key).realized),'Receitas - despesas',F.monthSummary(st,key).realized>=0?'good':'danger','chart')}${metric('Dívida atual',F.money(debtTotal),'Saldo devedor dos contratos',debtTotal?'warn':'good','receipt')}</div><div class="grid-equal"><section class="panel"><div class="panel-head"><div><h3>Últimos 6 meses</h3><small>Entradas x saídas realizadas</small></div><div class="legend"><span><i></i>Receita</span><span><i class="expense"></i>Despesa</span></div></div><div class="chart">${summaries.map(x=>`<div class="bar-group"><div class="bar" style="height:${Math.max(2,Math.round(x.incomeRealized/max*100))}%" title="Receitas ${F.money(x.incomeRealized)}"></div><div class="bar expense" style="height:${Math.max(2,Math.round(x.expensesRealized/max*100))}%" title="Despesas ${F.money(x.expensesRealized)}"></div><label>${e(F.monthLabel(x.m).split(' ')[0].slice(0,3))}</label></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><h3>Despesas por categoria</h3><small>${e(F.monthLabel(key))}</small></div>${cats.length?cats.slice(0,8).map(x=>`<div class="budget-row"><div class="budget-meta"><strong>${e(F.categoryName(st,x.categoryId))}</strong><span>${F.money(x.amountCents)}</span></div><div class="progress"><span style="width:${Math.round(x.amountCents/catMax*100)}%"></span></div></div>`).join(''):empty('Sem dados para analisar','Registre gastos para construir os relatórios.','chart')}</section></div><div class="grid-equal"><section class="panel"><div class="panel-head"><h3>Indicadores do mês</h3></div>${indicatorRows(st,key)}</section><section class="panel"><div class="panel-head"><h3>Leitura rápida</h3></div>${quickReading(st,key)}</section></div>`, 'Relatórios', 'Evolução útil, sem encher a tela de gráficos');}
  function indicatorRows(st,key){const sm=F.monthSummary(st,key),cats=F.expenseByCategory(st,key),top=cats[0];const savings=sm.incomeRealized?Math.round(sm.realized/sm.incomeRealized*100):0;return `<div class="list"><div class="list-row"><div class="row-icon">${icon('target')}</div><div class="row-main"><strong>Taxa de sobra do mês</strong><span>Resultado / receitas realizadas</span></div><div class="row-amount">${savings}%</div></div><div class="list-row"><div class="row-icon">${icon('chart')}</div><div class="row-main"><strong>Categoria com maior gasto</strong><span>${top?e(F.categoryName(st,top.categoryId)):'Sem dados'}</span></div><div class="row-amount">${top?F.money(top.amountCents):'—'}</div></div><div class="list-row"><div class="row-icon">${icon('receipt')}</div><div class="row-main"><strong>Parcelas de dívidas previstas</strong><span>No mês selecionado</span></div><div class="row-amount">${F.money(sm.debtPlanned)}</div></div><div class="list-row"><div class="row-icon">${icon('card')}</div><div class="row-main"><strong>Faturas previstas</strong><span>No mês selecionado</span></div><div class="row-amount">${F.money(sm.cardPlanned)}</div></div></div>`}
  function quickReading(st,key){const sm=F.monthSummary(st,key),due=F.dueBuckets(st,F.monthKey(new Date())),budget=(st.budgets||[]).filter(b=>b.monthKey===key),sp=new Map(F.expenseByCategory(st,key).map(x=>[x.categoryId,x.amountCents])),over=budget.filter(b=>(sp.get(b.categoryId)||0)>b.limitCents);const items=[];items.push(sm.projected>=0?['good','O mês está projetado no positivo',`Sobra prevista de ${F.money(sm.projected)}.`]:['danger','O mês está projetado no negativo',`Faltam ${F.money(Math.abs(sm.projected))} para cobrir tudo que foi previsto.`]);if(due.overdue.length)items.push(['danger','Existem contas atrasadas',`${due.overdue.length} item(ns) precisam de atenção.`]);if(over.length)items.push(['warn','Há orçamento estourado',`${over.length} categoria(s) passaram do limite.`]);if(!due.overdue.length&&!over.length&&sm.projected>=0)items.push(['good','Os registros estão coerentes','Continue registrando até os gastos pequenos para manter essa leitura útil.']);return items.map(([kind,title,text])=>`<div class="alert-strip ${kind==='good'?'':kind}">${icon(kind==='danger'?'alert':kind==='warn'?'info':'check')}<div><strong>${e(title)}</strong><span>${e(text)}</span></div></div>`).join('')}

  function managePage(){
    const tabs=[['transactions','Movimentações'],['fixed_income','Receitas fixas'],['fixed_expense','Contas fixas'],['cards','Cartões'],['debts','Dívidas'],['catalogs','Cadastros'],['budget','Planejamento']];
    return shell(`<div class="section-title"><div><h2>Gerenciar dados</h2><p>Escolha o que quer fazer; o app pede somente o indispensável.</p></div></div>${manageShortcuts()}<div class="manage-tabs">${tabs.map(([k,l])=>`<button class="pill ${ui.manageTab===k?'active':''}" data-manage-tab="${k}">${l}</button>`).join('')}</div>${manageTabContent()}`, 'Gerenciar', 'Cadastrar e corrigir sem poluir as telas de consulta');
  }
  function manageShortcuts(){return `<div class="quick-manage-grid"><button class="quick-manage" data-action="quick"><span>${icon('receipt')}</span><strong>Gasto rápido</strong><small>PIX, débito ou dinheiro</small></button><button class="quick-manage" data-action="fixed-income"><span>${icon('wallet')}</span><strong>Salário / receita fixa</strong><small>Repete todos os meses</small></button><button class="quick-manage" data-action="fixed-expense"><span>${icon('calendar')}</span><strong>Conta fixa</strong><small>Sem exigir data de início</small></button><button class="quick-manage" data-action="card-purchase"><span>${icon('card')}</span><strong>Compra no cartão</strong><small>Escolha o cartão e as parcelas</small></button><button class="quick-manage" data-action="debt"><span>${icon('receipt')}</span><strong>Nova dívida</strong><small>Cadastre só o que souber</small></button></div>`}
  function manageTabContent(){return ({transactions:manageTransactions,fixed_income:()=>manageCommitments('income'),fixed_expense:()=>manageCommitments('expense'),cards:manageCards,debts:manageDebts,catalogs:manageCatalogs,budget:manageBudget})[ui.manageTab]();}
  function manageTransactions(){const st=ui.state,tx=(st.transactions||[]).slice().sort((a,b)=>(b.date||'').localeCompare(a.date||'')),transfers=(st.transfers||[]).slice().sort((a,b)=>(b.date||'').localeCompare(a.date||''));return `<div class="grid-equal"><section class="panel"><div class="panel-head"><div><h3>Entradas e saídas avulsas</h3><small>Para o que não se repete todo mês e não é compra no cartão</small></div><button class="primary-btn btn-sm" data-action="transaction">${icon('plus')} Novo</button></div>${tx.length?table(['Data','Descrição','Categoria','Conta','Valor',''],tx.map(t=>[t.date?F.dateLabel(t.date):'—',e(t.description||'Sem descrição'),e(F.categoryName(st,t.categoryId)),e(F.accountName(st,t.accountId)),`<span class="${t.kind==='income'?'row-amount income':'row-amount'}">${t.kind==='income'?'+':'-'} ${F.money(t.amountCents)}</span>`,actions('transaction',t.id)])):empty('Nenhuma movimentação','Use “Novo” ou o botão + para registrar.','receipt')}</section><section class="panel"><div class="panel-head"><div><h3>Transferências</h3><small>Movem dinheiro sem virar gasto ou renda</small></div><button class="secondary-btn btn-sm" data-action="transfer">${icon('transfer')} Transferir</button></div>${transfers.length?`<div class="list">${transfers.slice(0,12).map(t=>`<div class="list-row"><div class="row-icon">${icon('transfer')}</div><div class="row-main"><strong>${e(F.accountName(st,t.fromAccountId))} → ${e(F.accountName(st,t.toAccountId))}</strong><span>${t.date?F.dateLabel(t.date):'Data não informada'}${t.notes?' · '+e(t.notes):''}</span></div><div class="actions"><span class="row-amount">${F.money(t.amountCents)}</span><button class="action-btn danger" data-archive="transfer" data-id="${t.id}" title="Estornar transferência">${icon('trash')}</button></div></div>`).join('')}</div>`:empty('Sem transferências','Quando mover dinheiro entre duas contas, registre aqui.','transfer')}</section></div>`}
  function manageCommitments(kind){
    const st=ui.state,key=ui.month,list=(st.commitments||[]).filter(c=>c.kind===kind),payments=(st.commitmentPayments||[]).filter(p=>F.byId(st,'commitments',p.commitmentId)?.kind===kind).slice().sort((a,b)=>(b.date||'').localeCompare(a.date||''));
    const income=kind==='income',title=income?'Receitas fixas':'Contas fixas',singular=income?'receita fixa':'conta fixa';
    return `<div class="grid-equal"><section class="panel"><div class="panel-head"><div><h3>${title}</h3><small>${income?'Salário, pensão, aluguel recebido e outras entradas mensais':'Energia, internet, aluguel, mensalidades e outras contas mensais'}</small></div><button class="primary-btn btn-sm" data-action="${income?'fixed-income':'fixed-expense'}">${icon('plus')} Nova ${singular}</button></div><div class="alert-strip" style="margin-bottom:10px">${icon('refresh')}<div><strong>Sem data final = continua todo mês</strong><span>Marcar como recebido/pago em um mês não encerra o valor fixo. Início, fim e vencimento são opcionais.</span></div></div>${list.length?`<div class="list">${list.map(c=>{const paid=F.commitmentPaid(st,c,key),expected=F.commitmentExpectedAmount(st,c,key),done=paid>=expected,period=!c.startMonth&&!c.endMonth?'Ativo desde o cadastro':`${c.startMonth?'Desde '+F.monthLabel(c.startMonth):'Desde o cadastro'}${c.endMonth?' · até '+F.monthLabel(c.endMonth):''}`,due=num(c.dueDay)?`Dia ${c.dueDay}`:'Sem dia fixo';return `<div class="list-row"><div class="row-icon">${icon(income?'wallet':'calendar')}</div><div class="row-main"><strong>${e(c.name)}</strong><span>${F.money(expected)} · ${due} · ${e(period)}${!c.active?' · Pausado':''}</span></div><div class="actions">${c.active?(done?'<span class="tag good">Este mês registrado</span>':`<button class="soft-btn btn-sm" data-action="pay-commitment" data-id="${c.id}">${income?'Receber':'Marcar pago'}</button>`):'<span class="tag">Pausado</span>'}<button class="action-btn" data-edit="commitment" data-id="${c.id}" title="Editar valor e dados">${icon('edit')}</button><button class="action-btn danger" data-archive="commitment" data-id="${c.id}" title="Arquivar">${icon('trash')}</button></div></div>`}).join('')}</div>`:empty(`Nenhuma ${singular}`,income?'Cadastre o salário uma única vez; ele continuará aparecendo nos meses seguintes.':'Cadastre a conta uma única vez; ela continuará aparecendo até você definir um fim ou pausar.','refresh')}</section><section class="panel"><div class="panel-head"><div><h3>${income?'Recebimentos':'Pagamentos'} registrados</h3><small>Histórico não encerra a recorrência</small></div></div>${payments.length?`<div class="list">${payments.slice(0,12).map(p=>{const c=F.byId(st,'commitments',p.commitmentId);return `<div class="list-row"><div class="row-icon">${icon('check')}</div><div class="row-main"><strong>${e(c?.name||singular)}</strong><span>${e(F.monthLabel(p.monthKey))} · ${p.date?F.dateLabel(p.date):'Data não informada'}</span></div><div class="actions"><span class="row-amount ${income?'income':''}">${F.money(p.amountCents)}</span><button class="action-btn danger" data-archive="commitment_payment" data-id="${p.id}" title="Estornar registro">${icon('trash')}</button></div></div>`}).join('')}</div>`:empty('Nenhum registro ainda',income?'Quando receber, registre aqui. No mês seguinte a receita fixa volta automaticamente.':'Quando pagar, registre aqui. No mês seguinte a conta fixa volta automaticamente.','check')}</section></div>`;
  }
  function manageCards(){
    const st=ui.state,key=ui.month,cards=st.cards||[];
    return `<div class="panel"><div class="panel-head"><div><h3>Cartões e compras</h3><small>Cada cartão guarda sua própria lista de compras</small></div><button class="primary-btn btn-sm" data-action="card">${icon('plus')} Novo cartão</button></div>${cards.length?`<div class="card-manage-list">${cards.map(c=>{const inv=F.invoiceFor(st,c.id,key),purchases=(st.cardPurchases||[]).filter(p=>p.cardId===c.id).slice().sort((a,b)=>(b.purchaseDate||'').localeCompare(a.purchaseDate||''));return `<div class="card-manage-item"><div class="card-manage-head"><div><strong>${e(c.name||'Meu cartão')}</strong><span>Fatura ${F.money(inv.amountCents)} · ${purchases.length} compra(s)</span></div><div class="section-actions"><button class="primary-btn btn-sm" data-action="card-purchase-for" data-id="${e(c.id)}">${icon('plus')} Adicionar compra</button><button class="secondary-btn btn-sm" data-card-open-route="${e(c.id)}">Ver cartão</button><button class="action-btn" data-edit="card" data-id="${e(c.id)}">${icon('edit')}</button></div></div>${purchases.length?`<div class="compact-purchases">${purchases.slice(0,4).map(p=>`<div><span>${e(p.description||'Compra no cartão')} · ${num(p.installments)||1}x</span><strong>${F.money(p.totalCents)}</strong></div>`).join('')}</div>`:'<div class="form-hint">Nenhuma compra cadastrada neste cartão.</div>'}</div>`}).join('')}</div>`:empty('Sem cartões','Cadastre um cartão e as compras poderão ser adicionadas diretamente nele.','card')}</div>`;
  }
  function cardManageHistory(st){return ''}

  function manageDebts(){const st=ui.state,debts=st.debts||[];return `<div class="grid-equal"><section class="panel"><div class="panel-head"><div><h3>Dívidas, empréstimos e financiamentos</h3><small>Cadastre o contrato, não apenas a parcela</small></div><button class="primary-btn btn-sm" data-action="debt">${icon('plus')} Nova dívida</button></div>${debts.length?`<div class="list">${debts.map(d=>`<div class="list-row"><div class="row-icon">${icon('receipt')}</div><div class="row-main"><strong>${e(d.name)}</strong><span>${e(debtTypeLabel(d.debtType))} · ${F.debtHasKnownBalance(d)?`saldo ${F.money(F.debtBalance(st,d))}`:'saldo não informado'}</span></div><div class="actions"><button class="action-btn" data-edit="debt" data-id="${d.id}">${icon('edit')}</button><button class="action-btn danger" data-archive="debt" data-id="${d.id}">${icon('trash')}</button></div></div>`).join('')}</div>`:empty('Nenhuma dívida cadastrada','Financiamento de carro, moto e empréstimos entram aqui.','receipt')}</section><section class="panel"><div class="panel-head"><div><h3>Pagamentos</h3><small>Registre principal e juros quando souber</small></div><button class="primary-btn btn-sm" data-action="debt-payment">${icon('check')} Registrar pagamento</button></div>${debtPaymentHistory(st)}</section></div>`}
  function debtPaymentHistory(st){const p=(st.debtPayments||[]).slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,10);return p.length?`<div class="list">${p.map(x=>`<div class="list-row"><div class="row-icon">${icon('check')}</div><div class="row-main"><strong>${e(F.byId(st,'debts',x.debtId)?.name||'Dívida')}</strong><span>Parcela de ${e(F.monthLabel(F.debtPaymentMonth(x)))} · pago em ${F.dateLabel(x.date)} · principal ${F.money(x.principalCents||x.amountCents)}${x.interestCents?` · juros ${F.money(x.interestCents)}`:''}</span></div><div class="actions"><span class="row-amount">${F.money(x.amountCents)}</span><button class="action-btn danger" data-archive="debt_payment" data-id="${x.id}" title="Estornar pagamento">${icon('trash')}</button></div></div>`).join('')}</div>`:empty('Sem pagamentos registrados','Ao pagar uma parcela, registre aqui para reduzir o saldo da dívida.','check')}
  function manageCatalogs(){const st=ui.state;return `<div class="grid-equal"><section class="panel"><div class="panel-head"><div><h3>Contas</h3><small>Banco, carteira ou dinheiro</small></div><button class="primary-btn btn-sm" data-action="account">${icon('plus')} Conta</button></div>${catalogList(st.accounts||[],'account',x=>x.name,x=>`${x.institution||''}${x.accountType?' · '+x.accountType:''}`,'bank')}</section><section class="panel"><div class="panel-head"><div><h3>Categorias</h3><small>Organização dos gastos e receitas</small></div><button class="primary-btn btn-sm" data-action="category">${icon('plus')} Categoria</button></div>${catalogList(st.categories||[],'category',x=>x.name,x=>`${x.kind==='income'?'Receita':'Despesa'}${x.parentId?' · Subcategoria':''}`,'target')}</section></div>`}
  function catalogList(list,type,title,sub,ic){return list.length?`<div class="list">${list.map(x=>`<div class="list-row"><div class="row-icon">${icon(ic)}</div><div class="row-main"><strong>${e(title(x))}</strong><span>${e(sub(x))}</span></div><div class="actions"><button class="action-btn" data-edit="${type}" data-id="${x.id}">${icon('edit')}</button><button class="action-btn danger" data-archive="${type}" data-id="${x.id}">${icon('trash')}</button></div></div>`).join('')}</div>`:empty('Nada cadastrado','Use o botão acima para criar.','plus')}
  function manageBudget(){const st=ui.state,key=ui.month,items=(st.budgets||[]).filter(b=>b.monthKey===key),goals=st.goals||[];return `<div class="grid-equal"><section class="panel"><div class="panel-head"><div><h3>Orçamento por categoria</h3><small>${e(F.monthLabel(key))}</small></div><button class="primary-btn btn-sm" data-action="budget">${icon('plus')} Limite</button></div>${items.length?catalogList(items,'budget',x=>F.categoryName(st,x.categoryId),x=>F.money(x.limitCents),'target'):empty('Sem limites neste mês','Crie valores máximos para categorias importantes.','target')}</section><section class="panel"><div class="panel-head"><div><h3>Metas</h3><small>Objetivos separados do orçamento mensal</small></div><button class="primary-btn btn-sm" data-action="goal">${icon('plus')} Meta</button></div>${goals.length?catalogList(goals,'goal',x=>x.name,x=>`${F.money(x.currentCents)} de ${F.money(x.targetCents)}`,'target'):empty('Sem metas','Reserva de emergência e objetivos aparecem aqui.','target')}</section></div>`}
  function table(headers,rows){return `<div class="table-wrap"><table class="data-table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
  function actions(type,id){return `<div class="actions"><button class="action-btn" data-edit="${type}" data-id="${id}" title="Editar">${icon('edit')}</button><button class="action-btn danger" data-archive="${type}" data-id="${id}" title="Arquivar">${icon('trash')}</button></div>`}

  async function settingsPage(){
    let info={path:S.isNative()?'Banco local':'Prévia',size:0,counts:{}}; try{info=await S.getDatabaseInfo()}catch{}
    const backups=await S.getBackups().catch(()=>[]);
    const sync=await S.getSyncPlatform().catch(()=>({platform:'preview',canSend:false,canReceive:false}));
    let syncBox=`<div class="alert-strip warn">${icon('info')}<div><strong>Disponível no aplicativo instalado</strong><span>Abra o SOS Finança no Windows ou Android para usar a sincronização local.</span></div></div>`;
    if(sync.canSend) syncBox=`<div class="alert-strip">${icon('refresh')}<div><strong>PC → celular pela mesma rede Wi-Fi</strong><span>O celular receberá uma cópia completa do banco deste PC. O servidor do PC usa sempre a porta 45454 e o mesmo código de compatibilidade para funcionar com o APK que já está instalado.</span></div></div><div class="info-box" style="margin-top:12px"><span>Conexão fixa</span><strong>Porta 45454. Código fixo, sem geração de chave temporária.</strong></div><div style="height:14px"></div><button class="primary-btn" data-action="sync-send">${icon('refresh')} Enviar dados deste PC</button>`;
    if(sync.canReceive) syncBox=`<div class="alert-strip">${icon('refresh')}<div><strong>Receber dados do seu PC</strong><span>No PC abra Configurações → Sincronização → Enviar dados deste PC. Depois digite abaixo o IP, a porta e a chave exibidos.</span></div></div><form data-form="sync-receive" style="margin-top:14px"><div class="form-grid"><div class="form-field"><label>IP do PC</label><input name="host" inputmode="decimal" placeholder="Ex.: 192.168.0.15"></div><div class="form-field"><label>Porta</label><input name="port" inputmode="numeric" placeholder="Ex.: 49152"></div><div class="form-field full"><label>Chave de sincronização</label><input name="code" maxlength="19" autocomplete="off" autocapitalize="characters" placeholder="XXXX-XXXX-XXXX-XXXX"></div></div><div class="alert-strip warn" style="margin:14px 0">${icon('alert')}<div><strong>O PC será a origem</strong><span>Ao continuar, o banco atual deste celular será guardado em backup e substituído pela cópia do PC.</span></div></div><button class="primary-btn" type="submit">${icon('download')} Receber do PC</button></form>`;
    return shell(`<div class="grid-equal"><section class="panel"><div class="panel-head"><h3>Esta instalação</h3><small>Sem conta online</small></div><form data-form="settings-profile"><div class="form-grid"><div class="form-field"><label>Nome</label><input name="name" value="${e(ui.state.profile?.name||'')}" placeholder="Usuário"></div><div class="form-field"><label>Uso</label><select name="usageMode"><option value="household" ${selected(ui.state.profile?.usageMode,'household')}>Gestão da casa</option><option value="personal" ${selected(ui.state.profile?.usageMode,'personal')}>Finanças pessoais</option></select></div><div class="form-field full"><label>Tema</label><select name="theme"><option value="system" ${selected(ui.state.profile?.theme,'system')}>Automático do sistema</option><option value="light" ${selected(ui.state.profile?.theme,'light')}>Claro</option><option value="dark" ${selected(ui.state.profile?.theme,'dark')}>Escuro</option></select></div></div><div style="height:12px"></div><button class="primary-btn btn-sm" type="submit">Salvar preferências</button></form></section><section class="panel"><div class="panel-head"><h3>Banco local</h3><small>Dados deste aparelho</small></div><div class="settings-grid"><div class="info-box"><span>Local</span><strong>${e(info.path||'')}</strong></div><div class="info-box"><span>Tamanho</span><strong>${formatBytes(info.size||0)}</strong></div></div><div class="alert-strip" style="margin:14px 0 0">${icon('lock')}<div><strong>Banco individual</strong><span>Esta instalação não compartilha dados financeiros com outros usuários.</span></div></div></section></div><div class="grid-equal"><section class="panel"><div class="panel-head"><div><h3>Backup</h3><small>Crie uma cópia antes de alterações importantes</small></div><button class="primary-btn btn-sm" data-action="backup">${icon('download')} Fazer backup</button></div>${S.isNative()?(backups.length?`<div class="list">${backups.slice(0,8).map(b=>`<div class="list-row"><div class="row-icon">${icon('download')}</div><div class="row-main"><strong>${e(b.name)}</strong><span>${formatBytes(b.size)}</span></div><button class="secondary-btn btn-sm" data-restore="${e(b.name)}">Restaurar</button></div>`).join('')}</div>`:empty('Nenhum backup ainda','Crie o primeiro backup local do banco SQLite.','download')):`<div class="alert-strip warn">${icon('info')}<div><strong>Modo de prévia</strong><span>A prévia HTML exporta JSON. O app instalado usa backup real do SQLite.</span></div></div>`}</section><section class="panel"><div class="panel-head"><h3>Sincronização PC ↔ celular</h3><small>Somente os seus próprios aparelhos</small></div>${syncBox}</section></div>`, 'Configurações', 'Instalação local, backup e sincronização');
  }
  function formatBytes(n){n=Number(n||0);if(n<1024)return `${n} B`;if(n<1048576)return `${(n/1024).toFixed(1)} KB`;return `${(n/1048576).toFixed(1)} MB`}
  function openSyncSendModal(session){
    modalRoot.innerHTML=`<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true"><div class="modal-head"><div><h2>Enviar dados para o celular</h2><p>Deixe esta janela aberta e conclua no celular em até 10 minutos.</p></div><button class="modal-close" type="button" data-close-modal>${icon('close')}</button></div><div class="modal-body"><div class="alert-strip">${icon('lock')}<div><strong>Mesma rede Wi-Fi</strong><span>Se o Windows pedir acesso ao firewall, permita apenas em redes privadas.</span></div></div><div class="sync-pair-grid"><div class="info-box"><span>IP do PC</span><strong>${e(session.ip)}</strong></div><div class="info-box"><span>Porta fixa</span><strong>${e(session.port)}</strong></div><div class="info-box full"><span>Código fixo para o celular atual</span><strong class="sync-code">${e(session.code)}</strong></div></div><div class="alert-strip warn">${icon('info')}<div><strong>No celular</strong><span>Abra Configurações → Sincronização, digite o IP acima, porta 45454 e o código fixo mostrado. Esses dois últimos não mudam entre sincronizações.</span></div></div></div><div class="modal-foot"><button class="secondary-btn" type="button" data-action="sync-stop">Cancelar sincronização</button><button class="primary-btn" type="button" data-close-modal>Deixar aguardando</button></div></div></div>`;
    if(!history.state?.modal)pushHistory(true);
  }

  function morePage(){return shell(`<div class="grid-2"><section class="panel"><div class="panel-head"><h3>Mais opções</h3></div><div class="list">${[['accounts','Contas','wallet'],['budget','Orçamento','target'],['reports','Relatórios','chart'],['manage','Gerenciar dados','edit'],['settings','Configurações','settings']].map(([r,l,ic])=>`<button class="list-row" style="border-top:0;border-left:0;border-right:0;background:transparent;width:100%;text-align:left" data-route="${r}"><div class="row-icon">${icon(ic)}</div><div class="row-main"><strong>${l}</strong><span>Abrir seção</span></div>${icon('chevronRight')}</button>`).join('')}</div></section></div>`, 'Mais', 'Acesse as outras áreas do SOS Finança');}

  async function renderApp(){
    if(!ui.state) await reload(false);
    if(!ui.state.profile){setupPage();return;}
    applyTheme();
    if(ui.route==='settings'){root.innerHTML=await settingsPage();return;}
    const pages={home:homePage,month:monthPage,accounts:accountsPage,cards:cardsPage,debts:debtsPage,budget:budgetPage,reports:reportsPage,manage:managePage,more:morePage};
    root.innerHTML=(pages[ui.route]||homePage)();
  }

  function options(list,value,label,blank='Selecione'){return `<option value="">${e(blank)}</option>${list.map(x=>`<option value="${e(value(x))}">${e(label(x))}</option>`).join('')}`}
  function accountOptions(){return options(ui.state.accounts||[],x=>x.id,x=>x.name,'Sem conta / não informar')}
  function categoryOptions(kind=''){const list=(ui.state.categories||[]).filter(c=>!kind||c.kind===kind);return options(list,x=>x.id,x=>cPath(x),'Sem categoria')}
  function cPath(c){const p=F.byId(ui.state,'categories',c.parentId);return p?`${p.name} › ${c.name}`:c.name}
  function cardOptions(){return options(ui.state.cards||[],x=>x.id,x=>x.name,'Selecione o cartão')}
  function debtOptions(){return options((ui.state.debts||[]).filter(d=>F.debtIsOpen(ui.state,d)),x=>x.id,x=>x.name,'Selecione a dívida')}

  function openModal(title,subtitle,body,formType,wide=false){modalRoot.innerHTML=`<div class="modal-backdrop" data-close-modal><div class="modal ${wide?'wide':''}" role="dialog" aria-modal="true"><div class="modal-head"><div><h2>${e(title)}</h2><p>${e(subtitle)}</p></div><button class="modal-close" type="button" data-close-modal>${icon('close')}</button></div><form data-form="${formType}"><div class="modal-body">${body}</div><div class="modal-foot"><button type="button" class="secondary-btn" data-close-modal>Cancelar</button><button type="submit" class="primary-btn">Salvar</button></div></form></div></div>`;if(!history.state?.modal)pushHistory(true);}
  function field(label,name,value='',type='text',extra='',full=false,hint=''){return `<div class="form-field ${full?'full':''}"><label>${e(label)}</label><input type="${type}" name="${name}" value="${e(value??'')}" ${extra}>${hint?`<div class="form-hint">${e(hint)}</div>`:''}</div>`}
  function selectField(label,name,html,value='',full=false){return `<div class="form-field ${full?'full':''}"><label>${e(label)}</label><select name="${name}" data-value="${e(value??'')}">${html}</select></div>`}
  function textarea(label,name,value='',full=true){return `<div class="form-field ${full?'full':''}"><label>${e(label)}</label><textarea name="${name}">${e(value??'')}</textarea></div>`}
  function moneyInput(label,name,cents=0,full=false,hint=''){return field(label,name,cents? (num(cents)/100).toFixed(2).replace('.',','):'','text','inputmode="decimal" placeholder="0,00"',full,hint)}
  function setModalSelects(){modalRoot.querySelectorAll('select[data-value]').forEach(sel=>{sel.value=sel.dataset.value||''})}

  function quickForm(){openModal('Gasto rápido','Valor primeiro; os demais campos são opcionais',`<div class="radio-cards"><label class="radio-card"><input type="radio" name="kind" value="expense" checked><strong>Despesa</strong><span>Compra, PIX, dinheiro, débito</span></label><label class="radio-card"><input type="radio" name="kind" value="income"><strong>Receita</strong><span>Valor recebido agora</span></label></div><div style="height:14px"></div><div class="form-grid">${moneyInput('Valor','amount',0,false)}${field('Descrição (opcional)','description','','text','placeholder="Ex.: Bombom, padaria, PIX"')}${field('Data (opcional)','date',F.todayKey(),'date')}${selectField('Conta (opcional)','accountId',accountOptions())}${selectField('Categoria (opcional)','categoryId',categoryOptions('expense'))}${selectField('Forma de pagamento (opcional)','paymentMethod','<option value="">Não informar</option><option>PIX</option><option>Débito</option><option>Dinheiro</option><option>Outro</option>','')}${textarea('Observação (opcional)','notes','')}</div>`,'quick');setModalSelects();bindKindCategory();}
  function bindKindCategory(){const form=modalRoot.querySelector('form');form?.querySelectorAll('input[name="kind"]').forEach(r=>r.addEventListener('change',()=>{const sel=form.querySelector('[name="categoryId"]');if(sel)sel.innerHTML=categoryOptions(r.value)}))}

  function openEntityForm(type,item={}){
    if(type==='transaction'){openModal(item.id?'Editar movimentação':'Nova movimentação','Só valor é indispensável; o restante pode ser completado depois',`<input type="hidden" name="id" value="${e(item.id||'')}"><div class="form-grid">${selectField('Tipo','kind','<option value="expense">Despesa</option><option value="income">Receita</option>',item.kind||'expense')}${moneyInput('Valor','amount',item.amountCents)}${field('Descrição (opcional)','description',item.description||'','text','placeholder="Ex.: Padaria, diária, venda"')}${field('Data (opcional)','date',item.date||F.todayKey(),'date')}${selectField('Categoria (opcional)','categoryId',categoryOptions(item.kind||'expense'),item.categoryId)}${selectField('Conta (opcional)','accountId',accountOptions(),item.accountId)}${selectField('Forma de pagamento (opcional)','paymentMethod','<option value="">Não informar</option><option>PIX</option><option>Débito</option><option>Dinheiro</option><option>Outro</option>',item.paymentMethod||'')}${textarea('Observação (opcional)','notes',item.notes||'')}</div>`,'transaction');setModalSelects();modalRoot.querySelector('[name="kind"]')?.addEventListener('change',ev=>modalRoot.querySelector('[name="categoryId"]').innerHTML=categoryOptions(ev.target.value));return}
    if(type==='account'){openModal(item.id?'Editar conta':'Nova conta','Você pode começar só com o nome e saldo',`<input type="hidden" name="id" value="${e(item.id||'')}"><div class="form-grid">${field('Nome (opcional)','name',item.name||'','text','placeholder="Ex.: Conta principal"')}${field('Instituição (opcional)','institution',item.institution||'','text','placeholder="Ex.: Caixa, Nubank"')}${selectField('Tipo (opcional)','accountType','<option>Conta corrente</option><option>Conta digital</option><option>Poupança</option><option>Carteira / Dinheiro</option><option>Outro</option>',item.accountType||'Conta corrente')}${moneyInput('Saldo inicial (opcional)','openingBalance',item.openingBalanceCents,false,'Use o saldo real quando começar; pode editar depois.')}</div>`,'account');setModalSelects();return}
    if(type==='transfer'){openModal('Transferir entre contas','Escolha as duas contas e o valor',`<div class="form-grid">${selectField('Sai de','fromAccountId',accountOptions())}${selectField('Entra em','toAccountId',accountOptions())}${moneyInput('Valor','amount')}${field('Data (opcional)','date',F.todayKey(),'date')}${textarea('Observação (opcional)','notes','')}</div>`,'transfer');return}
    if(type==='commitment'){
      const income=(item.kind||'expense')==='income';
      openModal(item.id?`Editar ${income?'receita fixa':'conta fixa'}`:`Nova ${income?'receita fixa':'conta fixa'}`,'Cadastre uma vez e ela continua todos os meses até você pausar ou definir um fim',`<input type="hidden" name="id" value="${e(item.id||'')}"><div class="form-grid">${selectField('Tipo','kind','<option value="expense">Conta / despesa fixa</option><option value="income">Salário / receita fixa</option>',item.kind||'expense')}${field('Nome (opcional)','name',item.name||'','text',`placeholder="${income?'Ex.: Salário':'Ex.: Internet'}"`)}${moneyInput('Valor mensal','amount',item.amountCents,false,'Esse valor pode ser editado depois.')}${field('Dia de vencimento/recebimento (opcional)','dueDay',item.dueDay||'','number','min="1" max="31" placeholder="Ex.: 5"')}${selectField('Categoria (opcional)','categoryId',categoryOptions(item.kind||'expense'),item.categoryId)}${selectField('Conta padrão (opcional)','accountId',accountOptions(),item.accountId)}${field('Começa em (opcional)','startMonth',item.startMonth||'','month','',false,'Se não lembra quando começou, deixe vazio. O app considera a recorrência ativa.')}${field('Termina em (opcional)','endMonth',item.endMonth||'','month','',false,'Deixe vazio para continuar todos os meses.')}${selectField('Status','active','<option value="true">Ativo todos os meses</option><option value="false">Pausado</option>',String(item.active!==false))}${textarea('Observação (opcional)','notes',item.notes||'')}</div>`,'commitment',true);setModalSelects();modalRoot.querySelector('[name="kind"]')?.addEventListener('change',ev=>modalRoot.querySelector('[name="categoryId"]').innerHTML=categoryOptions(ev.target.value));return}
    if(type==='commitment_payment'){const c=item;const expected=F.commitmentExpectedAmount(ui.state,c,ui.month);const remaining=Math.max(0,expected-F.commitmentPaid(ui.state,c,ui.month));openModal(c.kind==='income'?'Registrar recebimento':'Registrar pagamento',c.name||'Valor fixo',`<input type="hidden" name="commitmentId" value="${e(c.id)}"><div class="form-grid">${field('Mês de referência (opcional)','monthKey',ui.month,'month')}${moneyInput('Valor','amount',remaining||c.amountCents)}${field('Data (opcional)','date',F.todayKey(),'date')}${selectField('Conta (opcional)','accountId',accountOptions(),c.accountId)}</div><div class="alert-strip" style="margin:10px 0 0">${icon('refresh')}<div><strong>Isso não encerra o valor fixo</strong><span>No próximo mês ele aparecerá novamente automaticamente.</span></div></div>`,'commitment_payment');setModalSelects();return}
    if(type==='card'){openModal(item.id?'Editar cartão':'Novo cartão','Nome, limite, fechamento e vencimento podem ser completados depois',`<input type="hidden" name="id" value="${e(item.id||'')}"><div class="form-grid">${field('Nome (opcional)','name',item.name||'','text','placeholder="Ex.: Nubank"')}${field('Banco (opcional)','bank',item.bank||'','text','placeholder="Ex.: Nubank"')}${field('Bandeira (opcional)','brand',item.brand||'','text','placeholder="Visa, Mastercard..."')}${field('Últimos 4 dígitos (opcional)','last4',item.last4||'','text','maxlength="4" inputmode="numeric"')}${moneyInput('Limite (opcional)','limit',item.limitCents)}${field('Fecha dia (opcional)','closeDay',item.closeDay||'','number','min="1" max="31" placeholder="Ex.: 18"')}${field('Vence dia (opcional)','dueDay',item.dueDay||'','number','min="1" max="31" placeholder="Ex.: 25"')}${selectField('Conta usada para pagar (opcional)','accountId',accountOptions(),item.accountId)}</div>`,'card');setModalSelects();return}
    if(type==='card_purchase'){openModal(item.id?'Editar compra':'Adicionar compra ao cartão','Só cartão e valor são necessários; data de hoje e 1 parcela são assumidos se deixar vazio',`<input type="hidden" name="id" value="${e(item.id||'')}"><div class="form-grid">${selectField('Cartão','cardId',cardOptions(),item.cardId)}${field('Descrição (opcional)','description',item.description||'','text','placeholder="Ex.: Geladeira, mercado"')}${moneyInput('Valor total','total',item.totalCents)}${field('Data da compra (opcional)','purchaseDate',item.purchaseDate||F.todayKey(),'date')}${field('Parcelas (opcional)','installments',item.installments||1,'number','min="1" max="120"')}${selectField('Categoria (opcional)','categoryId',categoryOptions('expense'),item.categoryId)}${textarea('Observação (opcional)','notes',item.notes||'')}</div>`,'card_purchase');setModalSelects();return}
    if(type==='card_payment'){openModal('Pagar fatura','O pagamento baixa a conta bancária; as compras continuam no histórico',`<div class="form-grid">${selectField('Cartão','cardId',cardOptions(),item.cardId)}${field('Fatura de (opcional)','invoiceMonth',item.invoiceMonth||ui.month,'month')}${moneyInput('Valor pago','amount')}${field('Data (opcional)','date',F.todayKey(),'date')}${selectField('Conta de saída (opcional)','accountId',accountOptions(),item.accountId)}</div><div class="form-hint">Confira o valor calculado na tela do cartão antes de registrar.</div>`,'card_payment');setModalSelects();return}
    if(type==='debt'){const hasPayments=item.id&&(ui.state.debtPayments||[]).some(p=>p.debtId===item.id),hasKnown=F.debtHasKnownBalance(item);openModal(item.id?'Editar dívida':'Nova dívida','Não lembra quando começou ou quanto falta? Sem problema. Cadastre o que sabe e complete depois.',`<input type="hidden" name="id" value="${e(item.id||'')}"><div class="form-grid">${selectField('Tipo','debtType','<option value="loan">Empréstimo</option><option value="car">Financiamento de carro</option><option value="motorcycle">Financiamento de moto</option><option value="card">Dívida de cartão</option><option value="personal">Dívida pessoal</option><option value="other">Outra dívida</option>',item.debtType||'loan')}${field('Nome (opcional)','name',item.name||'','text','placeholder="Ex.: Financiamento do carro"')}${field('Credor / instituição (opcional)','creditor',item.creditor||'','text','placeholder="Banco ou pessoa"')}${field('Data de início (opcional)','startDate',item.startDate||'','date','',false,'Deixe vazio se não lembrar.')}${moneyInput('Valor original (opcional)','original',item.originalCents)}${moneyInput('Total contratado (opcional)','totalContract',item.totalContractCents)}${field('Saldo devedor atual (opcional)','balance',hasKnown?F.debtBalance(ui.state,item)/100:'','text',`inputmode="decimal" placeholder="0,00" ${hasPayments&&hasKnown?'readonly':''}`,false,hasPayments&&hasKnown?'Bloqueado porque a dívida já tinha saldo conhecido e há pagamentos registrados.':hasPayments?'Informe o saldo atual se descobriu agora; o app preserva os pagamentos anteriores.':'Se não souber agora, deixe vazio e informe depois.')}${moneyInput('Valor da parcela (opcional)','installment',item.installmentCents)}${field('Parcelas totais (opcional)','installmentsTotal',item.installmentsTotal||'','number','min="0" max="600"')}${field('Parcelas já pagas antes do app (opcional)','installmentsPaid',item.installmentsPaid||'','number','min="0" max="600"')}${field('Vence dia (opcional)','dueDay',item.dueDay||'','number','min="1" max="31"')}${field('Juros % (opcional)','interestRate',item.interestRate||'','text','inputmode="decimal"')}${selectField('Prioridade (opcional)','priority','<option value="3">Normal</option><option value="2">Média</option><option value="1">Alta</option>',item.priority||3)}${textarea('Observação (opcional)','notes',item.notes||'')}</div>`,'debt',true);setModalSelects();return}
    if(type==='debt_payment'){openModal('Registrar pagamento de dívida','Mês da parcela, juros e amortização podem ficar vazios se você não souber',`<div class="form-grid">${selectField('Dívida','debtId',debtOptions(),item.debtId)}${field('Parcela referente ao mês (opcional)','installmentMonth',ui.month,'month','',false,'Se vazio, o app usa o mês da data do pagamento.')}${moneyInput('Valor pago','amount')}${moneyInput('Amortização / principal (opcional)','principal',0,false,'Se vazio, o app considera pagamento menos juros como redução estimada quando houver saldo conhecido.')}${moneyInput('Juros no pagamento (opcional)','interest')}${field('Data (opcional)','date',F.todayKey(),'date')}${selectField('Conta de saída (opcional)','accountId',accountOptions())}${textarea('Observação (opcional)','notes','')}</div>`,'debt_payment');setModalSelects();return}
    if(type==='category'){const parents=(ui.state.categories||[]).filter(c=>c.id!==item.id);openModal(item.id?'Editar categoria':'Nova categoria','Nome é o único dado realmente importante',`<input type="hidden" name="id" value="${e(item.id||'')}"><div class="form-grid">${field('Nome','name',item.name||'','text','placeholder="Ex.: Farmácia"')}${selectField('Tipo','kind','<option value="expense">Despesa</option><option value="income">Receita</option>',item.kind||'expense')}${selectField('Subcategoria de (opcional)','parentId',options(parents,x=>x.id,x=>x.name,'Categoria principal'),item.parentId)}${field('Ícone interno (opcional)','icon',item.icon||'tag','text','placeholder="tag"')}</div>`,'category');setModalSelects();return}
    if(type==='budget'){openModal(item.id?'Editar limite':'Novo limite mensal','Defina somente se essa categoria precisa de teto',`<input type="hidden" name="id" value="${e(item.id||'')}"><div class="form-grid">${selectField('Categoria','categoryId',categoryOptions('expense'),item.categoryId)}${field('Mês (opcional)','monthKey',item.monthKey||ui.month,'month')}${moneyInput('Limite','limit',item.limitCents)}</div>`,'budget');setModalSelects();return}
    if(type==='goal'){openModal(item.id?'Editar meta':'Nova meta','Data é opcional',`<input type="hidden" name="id" value="${e(item.id||'')}"><div class="form-grid">${field('Nome (opcional)','name',item.name||'','text','placeholder="Ex.: Reserva de emergência"')}${moneyInput('Valor alvo','target',item.targetCents)}${moneyInput('Valor já guardado (opcional)','current',item.currentCents)}${field('Data alvo (opcional)','dueDate',item.dueDate||'','date')}</div>`,'goal');return}
  }

  async function saveForm(form){
    const fd=new FormData(form), type=form.dataset.form, g=name=>String(fd.get(name)||'').trim(), cents=name=>F.centsFromInput(g(name));
    try{
      const positive=(name,label)=>{const value=cents(name);if(value<=0)throw new Error(`${label} precisa ser maior que zero.`);return value};
      const optionalInt=(name,min,max)=>{if(!g(name))return 0;const value=num(g(name));if(!Number.isInteger(value)||value<min||value>max)throw new Error(`O valor de ${name} precisa estar entre ${min} e ${max}.`);return value};
      const assertCategoryKind=(categoryId,kind)=>{if(!categoryId)return;const category=F.byId(ui.state,'categories',categoryId);if(!category||category.kind!==kind)throw new Error('A categoria escolhida não corresponde ao tipo do lançamento.')};
      if(type==='setup'||type==='settings-profile'){await S.saveEntity('profile',{name:g('name')||'Usuário',usageMode:g('usageMode')||'personal',theme:g('theme')||ui.state?.profile?.theme||'system'});await reload();closeModal(false);toast('Preferências salvas');return}
      if(type==='sync-receive'){const host=g('host'),port=Number(g('port')),code=g('code');if(!host||!port||!code)throw new Error('Informe IP, porta e chave mostrados no PC.');if(!confirm('Receber os dados do PC agora? O SOS Finança fará backup deste celular e depois substituirá o banco local pela cópia do PC.'))return;const result=await S.receiveSyncFromPc(host,port,code);await reload();toast(result?.message||'Sincronização concluída');return}
      if(type==='quick'||type==='transaction'){const kind=g('kind')||'expense';assertCategoryKind(g('categoryId'),kind);await S.saveEntity('transaction',{id:g('id')||undefined,kind,amountCents:positive('amount','O valor'),description:g('description')||(kind==='income'?'Receita':'Despesa'),date:g('date')||F.todayKey(),categoryId:g('categoryId')||null,accountId:g('accountId')||null,paymentMethod:g('paymentMethod'),notes:g('notes')});}
      else if(type==='account')await S.saveEntity('account',{id:g('id')||undefined,name:g('name')||g('institution')||'Minha conta',institution:g('institution'),accountType:g('accountType')||'Conta corrente',openingBalanceCents:cents('openingBalance')});
      else if(type==='transfer'){if(!g('fromAccountId')||!g('toAccountId'))throw new Error('Escolha as duas contas.');if(g('fromAccountId')===g('toAccountId'))throw new Error('Escolha contas diferentes.');await S.saveEntity('transfer',{fromAccountId:g('fromAccountId'),toAccountId:g('toAccountId'),amountCents:positive('amount','O valor'),date:g('date')||F.todayKey(),notes:g('notes')});}
      else if(type==='commitment'){const kind=g('kind')||'expense';assertCategoryKind(g('categoryId'),kind);const start=g('startMonth'),end=g('endMonth');if(end&&start&&end<start)throw new Error('O mês final não pode ser anterior ao mês inicial.');await S.saveEntity('commitment',{id:g('id')||undefined,name:g('name')||(kind==='income'?'Salário / receita fixa':'Conta fixa'),kind,amountCents:positive('amount','O valor mensal'),dueDay:optionalInt('dueDay',1,31),categoryId:g('categoryId')||null,accountId:g('accountId')||null,startMonth:start,endMonth:end||null,active:g('active')!=='false',notes:g('notes')});}
      else if(type==='commitment_payment'){const c=F.byId(ui.state,'commitments',g('commitmentId'));if(!c)throw new Error('Valor fixo não encontrado.');const month=g('monthKey')||ui.month,amount=positive('amount','O valor'),expected=F.commitmentExpectedAmount(ui.state,c,month),remaining=Math.max(0,expected-F.commitmentPaid(ui.state,c,month));if(remaining<=0)throw new Error('Este mês já está totalmente registrado.');if(amount>remaining)throw new Error(`O valor excede o restante previsto de ${F.money(remaining)}.`);await S.saveEntity('commitment_payment',{commitmentId:c.id,monthKey:month,amountCents:amount,expectedAmountCents:expected,date:g('date')||F.todayKey(),accountId:g('accountId')||null});}
      else if(type==='card'){if(g('last4')&&!/^\d{4}$/.test(g('last4')))throw new Error('Se informar os últimos dígitos, use exatamente 4 números.');await S.saveEntity('card',{id:g('id')||undefined,name:g('name')||g('bank')||'Meu cartão',bank:g('bank'),brand:g('brand'),last4:g('last4'),limitCents:cents('limit'),closeDay:optionalInt('closeDay',1,31),dueDay:optionalInt('dueDay',1,31),accountId:g('accountId')||null});}
      else if(type==='card_purchase'){if(!g('cardId'))throw new Error('Escolha o cartão.');assertCategoryKind(g('categoryId'),'expense');const installments=g('installments')?optionalInt('installments',1,120):1;await S.saveEntity('card_purchase',{id:g('id')||undefined,cardId:g('cardId'),description:g('description')||'Compra no cartão',totalCents:positive('total','O valor total'),purchaseDate:g('purchaseDate')||F.todayKey(),installments:installments||1,categoryId:g('categoryId')||null,notes:g('notes')});}
      else if(type==='card_payment'){if(!g('cardId'))throw new Error('Escolha o cartão.');const invoiceMonth=g('invoiceMonth')||ui.month,invoice=F.invoiceFor(ui.state,g('cardId'),invoiceMonth),amount=positive('amount','O valor pago');if(invoice.amountCents<=0)throw new Error('Não existe fatura calculada para este cartão nesse mês.');if(invoice.remainingCents<=0)throw new Error('Esta fatura já está totalmente paga.');if(amount>invoice.remainingCents)throw new Error(`O pagamento excede o restante da fatura: ${F.money(invoice.remainingCents)}.`);await S.saveEntity('card_payment',{cardId:g('cardId'),invoiceMonth,amountCents:amount,date:g('date')||F.todayKey(),accountId:g('accountId')||null});}
      else if(type==='debt'){const original=cents('original'),contract=cents('totalContract'),existing=F.byId(ui.state,'debts',g('id')),hasPayments=existing&&(ui.state.debtPayments||[]).some(p=>p.debtId===existing.id),existingKnown=existing&&F.debtHasKnownBalance(existing),typedBalance=cents('balance'),paidPrincipal=existing?(ui.state.debtPayments||[]).filter(p=>p.debtId===existing.id).reduce((a,p)=>a+num(p.principalCents||p.amountCents),0):0,balance=hasPayments&&existingKnown?num(existing.balanceCents||existing.totalContractCents||existing.originalCents):(hasPayments&&typedBalance>0?typedBalance+paidPrincipal:typedBalance),installmentsTotal=g('installmentsTotal')?optionalInt('installmentsTotal',0,600):0,installmentsPaid=g('installmentsPaid')?optionalInt('installmentsPaid',0,600):0;if(installmentsTotal>0&&installmentsPaid>installmentsTotal)throw new Error('Parcelas já pagas não pode ser maior que o total.');const interestRate=Number(g('interestRate').replace(',','.'))||0;if(interestRate<0||interestRate>1000)throw new Error('A taxa de juros informada parece inválida.');const debtType=g('debtType')||'other';await S.saveEntity('debt',{id:g('id')||undefined,debtType,name:g('name')||g('creditor')||debtTypeLabel(debtType),creditor:g('creditor'),originalCents:original,totalContractCents:contract,balanceCents:balance,installmentCents:cents('installment'),installmentsTotal,installmentsPaid,dueDay:optionalInt('dueDay',1,31),interestRate,startDate:g('startDate'),status:'active',priority:Number(g('priority'))||3,notes:g('notes')});}
      else if(type==='debt_payment'){if(!g('debtId'))throw new Error('Escolha a dívida.');const debt=F.byId(ui.state,'debts',g('debtId'));if(!debt)throw new Error('Dívida não encontrada.');const amount=positive('amount','O valor pago'),interest=cents('interest'),explicitPrincipal=cents('principal'),principal=explicitPrincipal||Math.max(0,amount-interest);if(interest<0||principal<0)throw new Error('Principal e juros não podem ser negativos.');if(principal+interest>amount)throw new Error('Principal + juros não pode ser maior que o pagamento.');if(F.debtHasKnownBalance(debt)&&principal>F.debtBalance(ui.state,debt))throw new Error(`A amortização excede o saldo devedor atual de ${F.money(F.debtBalance(ui.state,debt))}.`);const date=g('date')||F.todayKey();await S.saveEntity('debt_payment',{debtId:debt.id,installmentMonth:g('installmentMonth')||F.monthKey(date),amountCents:amount,principalCents:principal,interestCents:interest,date,accountId:g('accountId')||null,notes:g('notes')});}
      else if(type==='category'){const kind=g('kind')||'expense',parent=g('parentId')?F.byId(ui.state,'categories',g('parentId')):null;if(parent&&parent.kind!==kind)throw new Error('Uma subcategoria precisa ter o mesmo tipo da categoria principal.');await S.saveEntity('category',{id:g('id')||undefined,name:g('name')||'Nova categoria',kind,parentId:g('parentId')||null,icon:g('icon')||'tag'});}
      else if(type==='budget'){if(!g('categoryId'))throw new Error('Escolha a categoria.');const month=g('monthKey')||ui.month,existing=(ui.state.budgets||[]).find(b=>b.categoryId===g('categoryId')&&b.monthKey===month);await S.saveEntity('budget',{id:g('id')||existing?.id||undefined,categoryId:g('categoryId'),monthKey:month,limitCents:positive('limit','O limite')});}
      else if(type==='goal')await S.saveEntity('goal',{id:g('id')||undefined,name:g('name')||'Meta financeira',targetCents:positive('target','O valor alvo'),currentCents:cents('current'),dueDate:g('dueDate')||null,status:'active'});
      closeModal(false);await reload();toast('Salvo com sucesso');
    }catch(err){toast(err?.message||String(err),'danger')}
  }

  function getEntity(type,id){const map={account:'accounts',category:'categories',transaction:'transactions',commitment:'commitments',card:'cards',card_purchase:'cardPurchases',debt:'debts',budget:'budgets',goal:'goals'};return (ui.state[map[type]]||[]).find(x=>x.id===id)}

  root.addEventListener('click',async ev=>{
    const route=ev.target.closest('[data-route]');if(route){ui.route=route.dataset.route;ui.cardManageId=null;await renderApp();pushHistory(false);return}
    const shift=ev.target.closest('[data-month-shift]');if(shift){ui.month=F.addMonths(ui.month,Number(shift.dataset.monthShift));await renderApp();return}
    const mt=ev.target.closest('[data-manage-tab]');if(mt){ui.manageTab=mt.dataset.manageTab;await renderApp();return}
    const cardOpen=ev.target.closest('[data-card-open]');if(cardOpen){ui.cardManageId=cardOpen.dataset.cardOpen;await renderApp();pushHistory(false);return}
    const cardRoute=ev.target.closest('[data-card-open-route]');if(cardRoute){ui.cardManageId=cardRoute.dataset.cardOpenRoute;ui.route='cards';await renderApp();pushHistory(false);return}
    if(ev.target.closest('[data-theme-toggle]')){const next=document.documentElement.dataset.theme==='dark'?'light':'dark';await S.saveEntity('profile',{...ui.state.profile,theme:next});await reload();return}
    const action=ev.target.closest('[data-action]');if(action){const a=action.dataset.action,id=action.dataset.id;if(a==='quick')quickForm();else if(a==='transaction')openEntityForm('transaction');else if(a==='transfer')openEntityForm('transfer');else if(a==='commitment')openEntityForm('commitment');else if(a==='fixed-income')openEntityForm('commitment',{kind:'income'});else if(a==='fixed-expense')openEntityForm('commitment',{kind:'expense'});else if(a==='pay-commitment')openEntityForm('commitment_payment',getEntity('commitment',id));else if(a==='card')openEntityForm('card');else if(a==='card-purchase')openEntityForm('card_purchase');else if(a==='card-purchase-for')openEntityForm('card_purchase',{cardId:id});else if(a==='card-payment')openEntityForm('card_payment');else if(a==='card-payment-for')openEntityForm('card_payment',{cardId:id,invoiceMonth:ui.month});else if(a==='debt')openEntityForm('debt');else if(a==='debt-payment')openEntityForm('debt_payment');else if(a==='account')openEntityForm('account');else if(a==='category')openEntityForm('category');else if(a==='budget')openEntityForm('budget');else if(a==='goal')openEntityForm('goal');else if(a==='backup'){try{const p=await S.makeBackup();toast(`Backup criado: ${p}`);await renderApp()}catch(err){toast(err.message,'danger')}}else if(a==='sync-send'){try{const session=await S.startSyncServer();openSyncSendModal(session)}catch(err){toast(err.message,'danger')}}else if(a==='sync-stop'){try{await S.stopSyncServer()}catch{}closeModal(true);toast('Sincronização cancelada')}return}
    const edit=ev.target.closest('[data-edit]');if(edit){openEntityForm(edit.dataset.edit,getEntity(edit.dataset.edit,edit.dataset.id));return}
    const archive=ev.target.closest('[data-archive]');if(archive){if(confirm('Arquivar este registro? O histórico principal será preservado sempre que possível.')){try{await S.archiveEntity(archive.dataset.archive,archive.dataset.id);await reload();toast('Registro arquivado')}catch(err){toast(err.message,'danger')}}return}
    const restore=ev.target.closest('[data-restore]');if(restore){if(confirm('Restaurar este backup? Será criado um backup de segurança do banco atual antes.')){try{await S.restoreBackup(restore.dataset.restore);await reload();toast('Backup restaurado')}catch(err){toast(err.message,'danger')}}}
  });

  root.addEventListener('submit',ev=>{if(ev.target.matches('form[data-form]')){ev.preventDefault();saveForm(ev.target)}});
  modalRoot.addEventListener('click',async ev=>{const stop=ev.target.closest?.('[data-action="sync-stop"]');if(stop){try{await S.stopSyncServer()}catch{}closeModal(true);toast('Sincronização cancelada');return}const direct=ev.target.matches?.('.modal-backdrop,[data-close-modal]'),button=ev.target.closest?.('button[data-close-modal]');if(direct||button)closeModal(true)});
  modalRoot.addEventListener('submit',ev=>{if(ev.target.matches('form[data-form]')){ev.preventDefault();saveForm(ev.target)}});
  document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&modalRoot.innerHTML)closeModal(true)});

  window.addEventListener('popstate',async ev=>{const state=ev.state;if(!state?.sosFinanca)return;ui.route=state.route||'home';ui.month=state.month||ui.month;ui.manageTab=state.manageTab||ui.manageTab;ui.cardManageId=state.cardManageId||null;modalRoot.innerHTML='';await renderApp();});

  matchMedia('(prefers-color-scheme: dark)').addEventListener?.('change',()=>{if(ui.state?.profile?.theme==='system')applyTheme()});

  ensureHistory();
  reload();
})();
